"""检索内核的存储与嵌入端口：Protocol + 确定性内存/替身实现。

端口只定义检索内核需要的最小面，不 import 平台资源模型——实现方（如 B7 的
Redis 快照与生产嵌入器）在端口外自行装配。
"""
from __future__ import annotations

import hashlib
import math
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Protocol, runtime_checkable


@runtime_checkable
class VectorStore(Protocol):
    """向量快照的 write-once 存储。

    ``publish`` 同一 ``snapshot_id`` 只允许一次：写入后快照不可变，重复发布抛
    ``ValueError``。读取面返回拷贝，调用方改返回值不影响存储内容。
    """

    def publish(
        self,
        snapshot_id: str,
        vectors: Mapping[str, Sequence[float]],
        meta: Mapping[str, str],
    ) -> None: ...

    def load(self, snapshot_id: str) -> dict[str, tuple[float, ...]] | None: ...

    def read_meta(self, snapshot_id: str) -> dict[str, str] | None: ...


@dataclass
class InMemoryVectorStore:
    """dict 存储的 :class:`VectorStore`，进程内生命周期。

    发布即转存不可变形态（向量 tuple、meta 浅拷贝 dict），此后拒绝对同一
    snapshot_id 的再次发布——write-once 语义是快照确定语义（R3）的存储侧前提。
    """

    _snapshots: dict[str, dict[str, tuple[float, ...]]]
    _meta: dict[str, dict[str, str]]

    def __init__(self) -> None:
        self._snapshots = {}
        self._meta = {}

    def publish(
        self,
        snapshot_id: str,
        vectors: Mapping[str, Sequence[float]],
        meta: Mapping[str, str],
    ) -> None:
        if snapshot_id in self._snapshots:
            raise ValueError(f"vector snapshot already published: {snapshot_id}")
        self._snapshots[snapshot_id] = {
            item_id: tuple(vector) for item_id, vector in vectors.items()
        }
        self._meta[snapshot_id] = dict(meta)

    def load(self, snapshot_id: str) -> dict[str, tuple[float, ...]] | None:
        """返回快照向量的拷贝；快照不存在返回 ``None``（缺失是正常路径，非异常）。"""
        snapshot = self._snapshots.get(snapshot_id)
        return dict(snapshot) if snapshot is not None else None

    def read_meta(self, snapshot_id: str) -> dict[str, str] | None:
        snapshot_meta = self._meta.get(snapshot_id)
        return dict(snapshot_meta) if snapshot_meta is not None else None


class QueryEmbeddingError(RuntimeError):
    """查询/语料嵌入失败——检索面按类型捕获并退回 BM25，不裸穿 requests 异常。"""


@runtime_checkable
class Embedder(Protocol):
    """文本嵌入端口：语料批量与查询单条两个入口。

    实现方在嵌入失败时应抛 :class:`QueryEmbeddingError`（而不是裸穿第三方异常）：
    融合检索面（``core.ranking``）按该类型捕获并自动退化为 BM25 单路。
    """

    def embed_corpus(self, texts: Sequence[str]) -> list[tuple[float, ...]]: ...

    def embed_query(self, text: str) -> tuple[float, ...]: ...


class MockEmbedder:
    """文本 hash → 确定性单位向量的真实替身（可运行实现，非打桩）。

    确定性来源是 ``hashlib.shake_256``：同文本任意两次调用逐位一致、跨进程一致，
    评测与测试因此可以离线复现（fusion-ranking §6）。归一化成单位向量是为了与
    真实嵌入器同语义——真实嵌入向量按惯例归一化，cosine 消费方在 Mock 与生产
    嵌入器之间行为一致。嵌入质量为零：只证明管线，不证明检索质量。
    """

    def __init__(self, dimensions: int = 8) -> None:
        self._dimensions = dimensions

    def embed_corpus(self, texts: Sequence[str]) -> list[tuple[float, ...]]:
        return [self.embed_query(text) for text in texts]

    def embed_query(self, text: str) -> tuple[float, ...]:
        digest = hashlib.shake_256((text or "").encode("utf-8")).digest(self._dimensions)
        vector = tuple(byte / 255.0 for byte in digest)
        norm = math.sqrt(sum(value * value for value in vector))
        return tuple(value / norm for value in vector)

"""本地 ONNX 嵌入器（信创/离线路；extras: ``local``，缺依赖时干净报错）。

依赖（onnxruntime/transformers/tokenizers/numpy）装在 ``local`` extra——Windows
ARM64 无 onnxruntime wheel，进主依赖会直接炸开发机安装。
"""
from __future__ import annotations

from collections.abc import Sequence

from agent_retrieval.core.ports import QueryEmbeddingError


class LocalEmbedder:
    """ONNX Runtime + transformers tokenizer 的本地嵌入器（mean-pooling + L2 归一化）。"""

    def __init__(self, *, model_dir: str, max_length: int = 512) -> None:
        try:
            import numpy as np
            import onnxruntime as ort
            from transformers import AutoTokenizer
        except ImportError as exc:
            raise RuntimeError(
                "LocalEmbedder 缺本地嵌入依赖（onnxruntime/transformers/tokenizers/numpy）；"
                "先安装 agent-retrieval[local]",
            ) from exc
        if not model_dir:
            raise RuntimeError("LocalEmbedder 需要 model_dir 指向 ONNX 模型目录")
        self._np = np
        self._session = ort.InferenceSession(model_dir, providers=["CPUExecutionProvider"])
        self._tokenizer = AutoTokenizer.from_pretrained(model_dir)
        self._max_length = max_length

    def embed_corpus(self, texts: Sequence[str]) -> list[tuple[float, ...]]:
        return self._embed(list(texts))

    def embed_query(self, text: str) -> tuple[float, ...]:
        return self._embed([text])[0]

    def _embed(self, texts: list[str]) -> list[tuple[float, ...]]:
        try:
            encoded = self._tokenizer(
                texts, padding=True, truncation=True,
                max_length=self._max_length, return_tensors="np",
            )
            input_names = {item.name for item in self._session.get_inputs()}
            last_hidden = self._session.run(
                None, {k: v for k, v in encoded.items() if k in input_names},
            )[0]
        except Exception as exc:
            raise QueryEmbeddingError(f"本地嵌入推理失败: {exc}") from exc
        mask = encoded["attention_mask"][..., None]
        summed = (last_hidden * mask).sum(1)
        counts = mask.sum(1).clip(min=1e-9)
        emb = summed / counts
        emb = emb / (self._np.linalg.norm(emb, axis=1, keepdims=True) + 1e-12)
        return [tuple(row) for row in emb]

"""Endpoint-specific request builders, layered over the generic `transport.prepare`."""

from collections.abc import Mapping
from typing import Any

import httpx2

from typesafe_sdk._core.config import Config
from typesafe_sdk._core.constants import MODELS_PATH, SYSTEM_ONE_PATH
from typesafe_sdk._core.json_types import JSONContent, JSONValue
from typesafe_sdk._core.question_types import Question
from typesafe_sdk._core.questions import normalize_questions
from typesafe_sdk._core.response_types import ListModelsResponse
from typesafe_sdk._core.transport import Request, ResponseT, prepare


def prepare_system_one(
    config: Config,
    state: JSONContent,
    questions: Mapping[str, Question],
    model: str | None,
    extra_body: Mapping[str, JSONValue | None] | None,
    timeout: float | httpx2.Timeout | None,
    headers: Mapping[str, str] | None,
    response_type: type[ResponseT],
) -> Request[ResponseT]:
    body: dict[str, Any] = {
        "state": state,
        "model": config.default_model if model is None else model,
        "questions": normalize_questions(questions),
    }
    if extra_body is not None:
        body.update(extra_body)
    return prepare(config, "POST", SYSTEM_ONE_PATH, body, timeout, headers, response_type)


def prepare_models(config: Config, timeout: float | httpx2.Timeout | None, headers: Mapping[str, str] | None) -> Request[ListModelsResponse]:
    return prepare(config, "GET", MODELS_PATH, None, timeout, headers, ListModelsResponse)

"""Question validation before JSON encoding."""

from collections.abc import Mapping, Sequence

from typesafe_sdk._core.errors import TypeSafeError
from typesafe_sdk._core.json_types import JSONContent
from typesafe_sdk._core.question_types import Choice, Noul, Question, Score


def normalize_questions(questions: Mapping[str, Question]) -> dict[str, Question]:
    if not questions:
        raise TypeSafeError("At least one question is required.")
    for name, question in questions.items():
        if isinstance(question, Score):
            _validate_score_criteria(name, question.criteria)
        elif not isinstance(question, (Noul, Choice)):
            if not isinstance(question, dict) or not isinstance(question.get("type"), str) or not question["type"]:
                raise TypeSafeError(f'Question "{name}" must be a question object or a dictionary with a nonempty string "type".')
            if question["type"] in ("choice", "score") and "criteria" not in question:
                raise TypeSafeError(f'Question "{name}" requires "criteria".')
            if question["type"] == "score":
                _validate_score_criteria(name, question["criteria"])
    return dict(questions)


def _validate_score_criteria(name: str, criteria: Sequence[JSONContent]) -> None:
    """Reject a score question with no criteria; at least one score is required."""
    if not criteria:
        raise TypeSafeError(f'Score question "{name}" has no criteria; at least one score is required.')

